// perspective hall helper (vanishing point vx,vy)
function hall(ctx, vx, vy, o) {
  const N = o.n || 7, spread = o.spread || 520, colH = o.colH || 1100, floorY = o.floorY || 1500;
  // floor
  ctx.fillStyle = lg(ctx, 0, vy, 0, H, [[0, shade(o.floor, -.3)], [1, o.floor]]); poly(ctx, [-400, H + 200, W + 400, H + 200, vx + 60, vy, vx - 60, vy]); ctx.fill();
  ctx.strokeStyle = 'rgba(0,0,0,.12)'; ctx.lineWidth = 2; for (let i = -10; i <= 10; i++) { ctx.beginPath(); ctx.moveTo(vx + i * 6, vy); ctx.lineTo(vx + i * 260, H + 200); ctx.stroke(); }
  for (let k = 1; k < 16; k++) { const zz = k * k * 6; const y = vy + zz; if (y > H) break; ctx.beginPath(); ctx.moveTo(-400, y); ctx.lineTo(W + 400, y); ctx.stroke(); }
  for (let i = N - 1; i >= 0; i--) {
    const zz = (i + 1 - (o.shift || 0)), k = 1 / (zz * .55 + .25);
    const by = vy + (floorY - vy) * k, h = colH * k, w = 110 * k, dark = clamp(1 - k * 1.3) * .5;
    [-1, 1].forEach(side => { const x = vx + side * spread * k; column(ctx, x, by, w, h, mix(o.col, '#1A1410', dark), side); });
    if (o.between) o.between(i, k, by);
  }
}

