  layer(ctx, .3, -t * 10, 0, () => { hills(ctx, 1130, 80, '#6A5A7E', 6, 0, .9); for (let i = 0; i < 12; i++) cypress(ctx, i * 110 + hash(i) * 30, 1140 - hash(i * 2) * 30, 90 + hash(i * 3) * 50, '#3E4A48'); });
