  // empire territory (red) fading
  const terr = 1 - ease(prog(t, 1.0, 2.4));
  if (terr > 0) { ctx.save(); ctx.globalAlpha = .45 * terr * (0.8 + .2 * Math.sin(T * 6)); ctx.fillStyle = '#B0352A'; ctx.beginPath(); const blob = [[-9, 43], [-9, 36], [-5, 35], [10, 33], [20, 31], [32, 30.5], [36.5, 31], [37, 37], [41, 41], [30, 45], [22, 45], [16, 47], [6, 49], [-4, 48]]; blob.forEach((p, i) => { const [x, y] = P(p); i ? ctx.lineTo(x, y) : ctx.moveTo(x, y); }); ctx.closePath(); ctx.fill(); ctx.restore();
    ctx.save(); ctx.globalAlpha = terr; ctx.strokeStyle = '#8A2E25'; ctx.lineWidth = 6; ctx.setLineDash([18, 12]); ctx.beginPath(); [[-9, 43], [-9, 36], [-5, 35], [10, 33], [20, 31], [32, 30.5], [36.5, 31], [37, 37], [41, 41], [30, 45], [22, 45], [16, 47], [6, 49], [-4, 48]].forEach((p, i) => { const [x, y] = P(p); i ? ctx.lineTo(x, y) : ctx.moveTo(x, y); }); ctx.closePath(); ctx.stroke(); ctx.restore();
    // crossed swords icons
    ctx.save(); ctx.globalAlpha = terr; ctx.font = '70px Anton'; ctx.textAlign = 'center'; ctx.fillStyle = '#8A2E25'; ctx.fillText('⚔', W * .5, 520); ctx.restore(); }
  // rail network
  const net = [['ROMA', 'GÁLIA'], ['ROMA', 'BIZÂNCIO'], ['GÁLIA', 'HISPÂNIA'], ['ROMA', 'CARTAGO'], ['CARTAGO', 'HISPÂNIA'], ['BIZÂNCIO', 'ANTIOQUIA'], ['ANTIOQUIA', 'ALEXANDRIA'], ['ATENAS', 'BIZÂNCIO'], ['ROMA', 'ATENAS'], ['CARTAGO', 'ALEXANDRIA']];
  const np = prog(t, 2.3, 4.4);
  net.forEach(([a, b], i) => { const q = clamp(np * 2.2 - i * .12); if (q <= 0) return; const [x0, y0] = P(CITIES[a]), [x1, y1] = P(CITIES[b]); const mx = (x0 + x1) / 2, my = (y0 + y1) / 2 - 40; ctx.save(); ctx.strokeStyle = '#3A2414'; ctx.lineWidth = 9; ctx.shadowColor = '#FFC861'; ctx.shadowBlur = 14; ctx.beginPath(); ctx.moveTo(x0, y0); for (let u = 0; u <= q; u += .05) { const x = (1 - u) ** 2 * x0 + 2 * (1 - u) * u * mx + u * u * x1, y = (1 - u) ** 2 * y0 + 2 * (1 - u) * u * my + u * u * y1; ctx.lineTo(x, y); } ctx.stroke(); ctx.strokeStyle = '#F5B83D'; ctx.lineWidth = 4; ctx.setLineDash([10, 8]); ctx.stroke(); ctx.restore();
    if (q >= 1) { const u = (T * .5 + i * .23) % 1; const x = (1 - u) ** 2 * x0 + 2 * (1 - u) * u * mx + u * u * x1, y = (1 - u) ** 2 * y0 + 2 * (1 - u) * u * my + u * u * y1; glow(ctx, x, y, 30, '#FFE08A', 1); circle(ctx, x, y, 7); ctx.fillStyle = '#fff'; ctx.fill(); } });
  Object.entries(CITIES).forEach(([n, c], i) => { const [x, y] = P(c); const pulse = n === 'ROMA' ? 1 + .15 * Math.sin(T * 5) : 1; circle(ctx, x, y, 11 * pulse); ctx.fillStyle = n === 'ROMA' ? '#B0352A' : '#3A2414'; ctx.fill(); circle(ctx, x, y, 5); ctx.fillStyle = '#F5E6C0'; ctx.fill(); ctx.font = `700 ${n === 'ROMA' ? 34 : 24}px Cardo`; ctx.textAlign = 'center'; ctx.fillStyle = '#3A2414'; ctx.fillText(n, x, y - 20); });
  ctx.restore();
